static std::uint64_t n(v::Kind k,v::MetricH6 m){return v::metricH6(unsigned(k),m).load();}
static v::Record rec(std::uint64_t tick,std::uint64_t sample=1){v::Record r{};r.kind=v::Kind::Cycle;r.tick=tick;r.sample=sample;r.sourceTick=tick-2;r.inputTick=tick-3;r.timeNs=tick*1000000;r.epoch=7;r.trackingEpoch=3;r.character=42;r.started=r.committed=r.nativeCalled=r.nativeReturned=r.restored=r.restoreOk=r.publishAttempted=r.packetPublished=r.published=true;std::strcpy(r.stage,"COMMITTED");std::strcpy(r.end,"PUBLISHED");return r;}
static std::string drain(std::uint64_t now){std::string out;v::drain(now,[&](const char* line){ck(std::strlen(line)<1499,"every summary/detail fits actual capture payload");ck(c::accept(line,now),"actual F7 domain accepts new line families");out+=line;out+='\n';});return out;}
static bool has(const std::string& s,const char* p){return s.find(p)!=s.npos;}
